public static int contarPerigosos(ArrayList<Bug> horda) {
    int perigosos = 0;
    for (int i = 0; i < horda.size(); i++) {
        if (horda.get(i).atacar() > 10) {
            perigosos++;
        }
    }
    return perigosos;
}
